glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv;
out vec4 color;
vec4 vert () { uv=a_texCoord; color=a_color; return cc_matViewProj*vec4(a_position,1.0); }
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec2 uv;
in vec4 color;
layout(std140) uniform CoreParams { vec4 params; vec4 bounds; };
uniform sampler2D maskTex;
vec4 over(vec4 a,vec4 b){return vec4(b.rgb*b.a+a.rgb*(1.0-b.a),b.a+a.a*(1.0-b.a));}
vec4 band(float u,bool topTier) {
  if(u<0.0||u>1.0)return vec4(0.0);
  vec4 a=topTier?vec4(255,150,40,0):vec4(255,98,15,0);
  vec4 b=topTier?vec4(255,184,60,.30):vec4(255,154,38,.32);
  vec4 c=topTier?vec4(255,234,135,.53):vec4(255,210,96,.64);
  vec4 d=topTier?vec4(255,108,20,0):vec4(255,76,8,0);
  float mid=topTier?.48:.46;
  vec4 v=u<mid?mix(a,b,u/mid):u<.62?mix(b,c,(u-mid)/(.62-mid)):mix(c,d,(u-.62)/.38);
  v.rgb/=255.0;return v;
}
vec4 field(vec2 p) {
  float time=params.x,grade=params.z,phase=mod(mod(time,1.85)+1.85,1.85);
  float pulse=exp(-pow((phase-.56)/.13,2.0));
  bool topTier=grade>29.0;
  float base=topTier?.05+pulse*.20:.045;
  vec4 col=vec4((topTier?vec3(255,100,24):vec3(255,73,15))/255.0*base,base);
  for(int i=0;i<3;i++) {
    float fi=float(i),count=topTier?3.0:grade>24.0?2.0:1.0;
    if(fi>=count)break;
    float halfHeight=topTier?55.0:grade>24.0?44.0:27.0;
    float pos=topTier?930.0-fract(time*.21+fi/3.0)*1090.0:bounds.z+halfHeight-fract(time*.24+fi/count)*(bounds.z-bounds.y+halfHeight*2.0);
    float center=bounds.x+(grade>24.0&&grade<29.0?(i==0?-48.0:48.0):0.0);
    float halfWidth=grade>24.0?76.0:40.0;
    if(topTier||abs(p.x-center)<=halfWidth)col=over(col,band((p.y-pos+halfHeight)/(halfHeight*2.0),topTier));
  }
  float travel=(phase-.40)/1.05;
  if(topTier&&travel>=0.0&&travel<=1.0) {
    float pos=bounds.w-travel*(bounds.w+30.0),u=(p.y-pos+90.0)/190.0;
    if(u>=0.0&&u<=1.0) {
      vec4 a=vec4(255,211,112,0),b=vec4(255,228,136,sin(3.141592653589793*travel)*.72),c=vec4(255,99,15,0);
      vec4 v=u<.5?mix(a,b,u*2.0):mix(b,c,(u-.5)*2.0);v.rgb/=255.0;col=over(col,v);
    }
  }
  return col*texture(maskTex,p/vec2(1024,1536)).a;
}
vec4 frag () {
  vec2 p=uv*vec2(1024,1536);vec4 col=field(p);
  if(params.w>0.0) {
    vec2 b=vec2(params.w,params.w);col=field(p)*.20;
    col+=(field(p+vec2(b.x,0))+field(p-vec2(b.x,0))+field(p+vec2(0,b.y))+field(p-vec2(0,b.y)))*.12;
    col+=(field(p+b)+field(p-b)+field(p+vec2(b.x,-b.y))+field(p+vec2(-b.x,b.y)))*.08;
  }
  return col*clamp(params.y,0.0,1.0)*color.a;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

